supplementalCommands.command:
bun --eval 'const ts = require("typescript"); const fs = require("fs");
for (const path of ["src/workspaceRepos.ts", "src/workspaceRepos.test.ts"]) {
 const source = ts.createSourceFile(path, fs.readFileSync(path, "utf8"), ts.ScriptTarget.Latest, true);
 const functions = [];
 function visit(node) {
  if (ts.isFunctionLike(node)) {
   const start = source.getLineAndCharacterOfPosition(node.getStart(source)).line + 1;
   const end = source.getLineAndCharacterOfPosition(node.end).line + 1;
   functions.push({start, end, lines: end-start+1, kind: ts.SyntaxKind[node.kind]});
  }
  ts.forEachChild(node, visit);
 }
 visit(source); console.log(JSON.stringify({path, lines: source.text.split("\n").length - 1, functions}));
}'

